rem = Reminders(os.path.join(HERE, "data", "reminders.json"))
when, what = ttk.Entry(root), ttk.Entry(root)
when.pack(); what.pack()

def add():
    try:
        rem.add(when.get().strip(), what.get().strip())
    except ValueError:
        messagebox.showerror("Reminder", "Write the time like 2026-04-01 08:00")

ttk.Button(root, text="Add reminder", command=add).pack()

for r in rem.due():
    root.bell()
    messagebox.showinfo("Reminder", r["text"])
